class Item:
 def __hash__(self): return 7
 def __eq__(self,other): raise RuntimeError("equal")
 def __lt__(self,other): raise RuntimeError("order")
 def __bool__(self): raise RuntimeError("truth")
 def __repr__(self): raise RuntimeError("repr")
 def __dir__(self): raise RuntimeError("directory")
item=Item()
values=(set((item,)),frozenset((item,)))
def forbidden(self): raise RuntimeError("rehash")
Item.__hash__=forbidden
print(*(len(dir(value)) for value in values))
print(*(len(value.__dir__()) for value in values))

class Item:
 def __hash__(self): return 7
 def __eq__(self,other): raise RuntimeError("equal")
 def __lt__(self,other): raise RuntimeError("order")
 def __bool__(self): raise RuntimeError("truth")
 def __repr__(self): raise RuntimeError("repr")
 def __dir__(self): raise RuntimeError("directory")
item=Item()
value=set((item,))
item.saved=value
d=value.__dir__
del value
del item
del Item
print(len(d()),next(iter(d.__self__)).saved is d.__self__)

